{{- if .Values.bundledSecret.enabled }}
{{/*
In-cluster Secret rendered from chart values. Convenient for local / minikube.
Disable with `bundledSecret.enabled=false` when an external mechanism (e.g. the
External Secrets Operator on Astra) provides the <release>-secrets Secret.
*/}}
{{- /*
AUTH_SECRET (Better Auth signing key) must be stable across upgrades, or every
upgrade would invalidate all sessions. Resolution order:
  1. Explicit .Values.authSecret if provided.
  2. The value already stored in the live Secret (preserved across upgrades).
  3. A freshly generated random secret on first install.
*/ -}}
{{- $existingSecret := (lookup "v1" "Secret" .Release.Namespace (include "auto-ontology.secretName" .)) -}}
{{- $authSecret := .Values.authSecret -}}
{{- if not $authSecret -}}
  {{- if and $existingSecret (index $existingSecret.data "AUTH_SECRET") -}}
    {{- $authSecret = index $existingSecret.data "AUTH_SECRET" | b64dec -}}
  {{- else -}}
    {{- $authSecret = randAlphaNum 48 -}}
  {{- end -}}
{{- end -}}
apiVersion: v1
kind: Secret
metadata:
  name: {{ include "auto-ontology.secretName" . }}
  labels:
    {{- include "auto-ontology.labels" . | nindent 4 }}
type: Opaque
stringData:
  AUTH_SECRET: {{ $authSecret | quote }}
  POSTGRES_USER: {{ .Values.postgresUser | quote }}
  POSTGRES_PASSWORD: {{ .Values.postgresPassword | quote }}
  POSTGRES_DATABASE: {{ .Values.postgresDatabase | quote }}
  POSTGRES_HOST: "postgres"
  POSTGRES_PORT: {{ .Values.postgres.service.port | quote }}
  INGESTION_SERVICE_URL: {{ printf "http://ingestion-service:%d" (int .Values.ingestion.service.port) | quote }}
  PGADMIN_EMAIL: {{ .Values.pgadminEmail | quote }}
  PGADMIN_PASSWORD: {{ .Values.pgadminPassword | quote }}
  # Shared default triplet. Every model triplet (REASONING / NON_REASONING /
  # EMBED / RERANK) falls back to these per field, so this single set of values
  # configures them all. EMBED_ENDPOINT/EMBED_MODEL below override just those.
  NVIDIA_API_KEY: {{ .Values.nvidiaApiKey | quote }}
  DEFAULT_MODELS_API_KEY: {{ .Values.defaultModelsApiKey | quote }}
  DEFAULT_MODELS_ENDPOINT: {{ .Values.defaultModelsEndpoint | default .Values.baseUrl | quote }}
  DEFAULT_MODELS_MODEL: {{ .Values.defaultModelsModel | default .Values.modelName | quote }}
  KUMO_RFM_API_KEY: {{ .Values.kumoRfmApiKey | quote }}
  KUMO_RFM_API_URL: {{ .Values.kumoRfmApiUrl | quote }}
  EMBED_ENDPOINT: {{ .Values.embedEndpoint | quote }}
  EMBED_MODEL: {{ .Values.embedModel | quote }}
  CONNECTION_STRINGS: {{ .Values.connectionStrings | quote }}
  VAULT_ADDR: {{ .Values.vaultAddr | quote }}
  VAULT_NAMESPACE: {{ .Values.vaultNamespace | quote }}
  VAULT_ROLE_ID: {{ .Values.vaultRoleId | quote }}
  VAULT_SECRET_ID: {{ .Values.vaultSecretId | quote }}
  VAULT_AUTH_MOUNT: {{ .Values.vaultAuthMount | quote }}
  VAULT_KV_MOUNT: {{ .Values.vaultKvMount | quote }}
  # Bootstrap admin, seeded/refreshed on frontend startup (lib/seed-admin.ts).
  # Required: self-service sign-up is disabled, so without these there would be
  # no way in. An empty value fails the install/upgrade rather than skipping.
  AUTO_ONTOLOGY_ADMIN_EMAIL: {{ required "adminEmail is required — pass --set adminEmail=<email> (self-service sign-up is disabled, so the bootstrap admin must be provided)." .Values.adminEmail | quote }}
  AUTO_ONTOLOGY_ADMIN_PASSWORD: {{ required "adminPassword is required — pass --set adminPassword=<password> (self-service sign-up is disabled, so the bootstrap admin must be provided)." .Values.adminPassword | quote }}
{{- end }}

